//! Difference vectors against `@morpho-org/blue-sdk`, generated by `scripts/vectors`.

use std::fmt::Debug;
use std::path::Path;

use alloy_primitives::{FixedBytes, U256};
use morpho_rs_sim::{
    get_liquidation_incentive_factor, BorrowPosition, LiquidationResult, Market, SimError,
};
use serde::de::DeserializeOwned;
use serde::Deserialize;

#[derive(Deserialize)]
struct Vectors<T> {
    cases: Vec<T>,
}

#[derive(Debug, Deserialize)]
struct MarketInput {
    total_supply_assets: U256,
    total_borrow_assets: U256,
    total_borrow_shares: U256,
    price: Option<U256>,
    lltv: U256,
}

impl MarketInput {
    fn market(&self) -> Market {
        Market::new_with_oracle(
            FixedBytes::ZERO,
            self.total_supply_assets,
            self.total_borrow_assets,
            U256::ZERO,
            self.total_borrow_shares,
            0,
            U256::ZERO,
            None,
            self.price,
            self.lltv,
        )
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Deserialize)]
struct PositionVector {
    collateral: U256,
    borrow_shares: U256,
}

impl From<BorrowPosition> for PositionVector {
    fn from(position: BorrowPosition) -> Self {
        Self {
            collateral: position.collateral,
            borrow_shares: position.borrow_shares,
        }
    }
}

#[derive(Debug, Deserialize)]
struct MathCase {
    market: MarketInput,
    position: PositionVector,
    repaid_shares_in: U256,
    seized_assets_in: U256,
    liquidation_incentive_factor: U256,
    collateral_value: Option<U256>,
    max_borrow_assets: Option<U256>,
    is_healthy: Option<bool>,
    health_factor: Option<U256>,
    liquidation_price: Option<U256>,
    liquidation_seized_assets: Option<U256>,
    liquidation_repaid_shares: Option<U256>,
    liquidation_repaid_assets: U256,
    seizable_collateral: Option<U256>,
}

#[derive(Debug, PartialEq, Eq, Deserialize)]
struct MarketAfter {
    total_supply_assets: U256,
    total_borrow_assets: U256,
    total_borrow_shares: U256,
}

#[derive(Debug, PartialEq, Eq, Deserialize)]
struct ResultVector {
    repaid_assets: U256,
    repaid_shares: U256,
    seized_assets: U256,
    bad_debt_assets: U256,
    bad_debt_shares: U256,
}

impl From<LiquidationResult> for ResultVector {
    fn from(result: LiquidationResult) -> Self {
        Self {
            repaid_assets: result.repaid_assets,
            repaid_shares: result.repaid_shares,
            seized_assets: result.seized_assets,
            bad_debt_assets: result.bad_debt_assets,
            bad_debt_shares: result.bad_debt_shares,
        }
    }
}

#[derive(Debug, PartialEq, Eq, Deserialize)]
struct Liquidated {
    market: MarketAfter,
    position: PositionVector,
    result: ResultVector,
}

#[derive(Debug, PartialEq, Eq, Deserialize)]
#[serde(untagged)]
enum LiquidateOutcome {
    Reverted { error: String },
    Liquidated(Box<Liquidated>),
}

#[derive(Debug, Deserialize)]
struct LiquidateCase {
    market: MarketInput,
    position: PositionVector,
    seized_assets_in: U256,
    repaid_shares_in: U256,
    expected: LiquidateOutcome,
}

fn load<T: DeserializeOwned>(name: &str) -> Vec<T> {
    let path = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/vectors")
        .join(name);
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    serde_json::from_str::<Vectors<T>>(&text)
        .unwrap_or_else(|e| panic!("{}: {e}", path.display()))
        .cases
}

fn mismatch<T: PartialEq + Debug>(field: &str, expected: T, actual: T) -> Option<String> {
    (expected != actual).then(|| format!("{field}: expected {expected:?}, got {actual:?}"))
}

fn assert_no_mismatches(name: &str, mismatches: Vec<String>) {
    assert!(
        mismatches.is_empty(),
        "{name}: {} mismatches, first: {:#?}",
        mismatches.len(),
        mismatches.iter().take(5).collect::<Vec<_>>()
    );
}

fn error_name(error: &SimError) -> String {
    match error {
        SimError::InconsistentLiquidationInput { .. } => "InconsistentLiquidationInput",
        SimError::UnknownOraclePrice { .. } => "UnknownOraclePrice",
        SimError::HealthyPosition { .. } => "HealthyPosition",
        SimError::DivisionByZero => "DivisionByZero",
        SimError::LiquidationExceedsPosition { .. } => "LiquidationExceedsPosition",
        other => return format!("{other:?}"),
    }
    .to_string()
}

fn outcome(
    result: Result<(Market, BorrowPosition, LiquidationResult), SimError>,
) -> LiquidateOutcome {
    match result {
        Ok((market, position, result)) => LiquidateOutcome::Liquidated(Box::new(Liquidated {
            market: MarketAfter {
                total_supply_assets: market.total_supply_assets,
                total_borrow_assets: market.total_borrow_assets,
                total_borrow_shares: market.total_borrow_shares,
            },
            position: position.into(),
            result: result.into(),
        })),
        Err(error) => LiquidateOutcome::Reverted {
            error: error_name(&error),
        },
    }
}

#[test]
fn market_math_matches_blue_sdk() {
    let cases = load::<MathCase>("market_math.json");
    assert_eq!(cases.len(), 10_000);
    let mismatches = cases
        .iter()
        .enumerate()
        .flat_map(|(index, case)| {
            let market = case.market.market();
            let PositionVector {
                collateral,
                borrow_shares,
            } = case.position;
            [
                mismatch(
                    "liquidation_incentive_factor",
                    case.liquidation_incentive_factor,
                    get_liquidation_incentive_factor(case.market.lltv),
                ),
                mismatch(
                    "collateral_value",
                    case.collateral_value,
                    market.get_collateral_value(collateral),
                ),
                mismatch(
                    "max_borrow_assets",
                    case.max_borrow_assets,
                    market.get_max_borrow_assets(collateral),
                ),
                mismatch(
                    "is_healthy",
                    case.is_healthy,
                    market.is_healthy(collateral, borrow_shares),
                ),
                mismatch(
                    "health_factor",
                    case.health_factor,
                    market.get_health_factor(collateral, borrow_shares),
                ),
                mismatch(
                    "liquidation_price",
                    case.liquidation_price,
                    market.get_liquidation_price(collateral, borrow_shares),
                ),
                mismatch(
                    "liquidation_seized_assets",
                    case.liquidation_seized_assets,
                    market.get_liquidation_seized_assets(case.repaid_shares_in),
                ),
                mismatch(
                    "liquidation_repaid_shares",
                    case.liquidation_repaid_shares,
                    market.get_liquidation_repaid_shares(case.seized_assets_in),
                ),
                mismatch(
                    "liquidation_repaid_assets",
                    case.liquidation_repaid_assets,
                    market.get_liquidation_repaid_assets(case.repaid_shares_in),
                ),
                mismatch(
                    "seizable_collateral",
                    case.seizable_collateral,
                    market.get_seizable_collateral(collateral, borrow_shares),
                ),
            ]
            .into_iter()
            .flatten()
            .map(move |message| format!("case {index}: {message}"))
        })
        .collect();
    assert_no_mismatches("market_math", mismatches);
}

#[test]
fn liquidate_matches_blue_sdk_port_of_morpho() {
    let cases = load::<LiquidateCase>("liquidate.json");
    assert_eq!(cases.len(), 10_000);
    let mismatches = cases
        .iter()
        .enumerate()
        .filter_map(|(index, case)| {
            let actual = outcome(case.market.market().liquidate(
                case.position.collateral,
                case.position.borrow_shares,
                case.seized_assets_in,
                case.repaid_shares_in,
            ));
            mismatch("liquidate", &case.expected, &actual)
                .map(|message| format!("case {index}: {message}"))
        })
        .collect();
    assert_no_mismatches("liquidate", mismatches);
}

#[test]
fn seizing_the_seizable_collateral_never_reverts() {
    let cases = load::<MathCase>("market_math.json");
    let failures = cases
        .iter()
        .enumerate()
        .filter_map(|(index, case)| {
            let market = case.market.market();
            let PositionVector {
                collateral,
                borrow_shares,
            } = case.position;
            let seizable = market
                .get_seizable_collateral(collateral, borrow_shares)
                .filter(|seizable| !seizable.is_zero())?;
            market
                .liquidate(collateral, borrow_shares, seizable, U256::ZERO)
                .err()
                .map(|error| format!("case {index}: seizing {seizable} failed with {error}"))
        })
        .collect();
    assert_no_mismatches("seizable_collateral", failures);
}
